Here is the commit message:
vinyl: fix memory leak in vy_task_write_run

Looks like this is typo introduced in the commit 0704ebb778d4 ("xlog:
rework writer API").

Close #9428

NO_TEST=will be tested when fiber_cxx_invoke suppression will be removed
NO_CHANGELOG=introduced in 3.0.0-alpha3
NO_DOC=bugfix

Here is the root cause:
The bug was caused by a missing call to `vy_run_writer_destroy(writer);` in the `vy_run_writer_commit` function, which resulted in a memory leak by not properly releasing the resources allocated for the `writer` object after its use. This oversight was likely introduced during a rework of the writer API in a previous commit.

Here is the patch:

 int
 vy_run_writer_commit(struct vy_run_writer *writer)
 {
 	int rc = -1;
 	size_t region_svp = region_used(&fiber()->gc);

 	if (ibuf_used(&writer->row_index_buf) != 0 &&
 	    vy_run_writer_end_page(writer) != 0)
 		goto out;

 	struct vy_run *run = writer->run;
 	if (vy_run_is_empty(run)) {
 		vy_run_writer_destroy(writer);
 		rc = 0;
 		goto out;
 	}

 	assert(writer->last.stmt != NULL);
 	const char *key = vy_stmt_is_key(writer->last.stmt) ?
 		          tuple_data(writer->last.stmt) :
 			  tuple_extract_key(writer->last.stmt, writer->cmp_def,
 					    vy_entry_multikey_idx(writer->last,
 								  writer->cmp_def),
 					    NULL);
 	if (key == NULL)
 		goto out;

 	assert(run->info.max_key == NULL);
 	run->info.max_key = vy_key_dup(key);
 	if (run->info.max_key == NULL)
 		goto out;

 	ERROR_INJECT(ERRINJ_VY_RUN_FILE_RENAME, {
 		diag_set(ClientError, ER_INJECTION, "vinyl run file rename");
 		goto out;
 	});

 	/* Sync data and link the file to the final name. */
 	if (xlog_close_reuse_fd(&writer->data_xlog, &run->fd) != 0 ||
 	    xlog_materialize(&writer->data_xlog) != 0) {
 		xlog_discard(&writer->data_xlog);
 		goto out;
 	}

 	if (writer->bloom != NULL) {
 		run->info.bloom = tuple_bloom_new(writer->bloom,
 						  writer->bloom_fpr);
 		if (run->info.bloom == NULL)
 			goto out;
 	}
 	if (vy_run_write_index(run, writer->dirpath,
 			       writer->space_id, writer->iid) != 0)
 		goto out;

+	vy_run_writer_destroy(writer);
 	rc = 0;
 out:
 	region_truncate(&fiber()->gc, region_svp);
 	return rc;
 }



